const SDK=window.__OIKOS_SDK__;const React=SDK.React.default??SDK.React;const{useCardConfig,useDashboard,useStyles,MdiIcon}=SDK;const h=React.createElement;
const DEF={alarmEntity:'alarm_control_panel.alarmo',garageEntity:'cover.portone_garage',guestEntity:'input_boolean.modalita_ospite'};
const border='1px solid var(--border-subtle,rgba(255,255,255,.08))';
function alarmLabel(v){return({disarmed:'Disinserito',armed_home:'Casa',armed_night:'Notte',armed_away:'Fuori',triggered:'ALLARME'})[v]||v||'—'}
function garageLabel(v){return({closed:'Chiuso',open:'Aperto',opening:'Apertura',closing:'Chiusura'})[v]||v||'—'}
function tile(s,icon,title,value,accent,onClick){return h('button',{type:'button',onClick,style:{minWidth:0,minHeight:86,borderRadius:s.tokens.radius.lg,padding:s.tokens.space.sm,background:'var(--bg-secondary)',border,color:s.tokens.color.primary,display:'grid',gridTemplateColumns:'34px minmax(0,1fr)',gap:s.tokens.space.sm,alignItems:'center',cursor:'pointer',textAlign:'left'}},h('div',{style:{width:34,height:34,borderRadius:s.tokens.radius.md,display:'flex',alignItems:'center',justifyContent:'center',background:`color-mix(in srgb, ${accent} 14%, transparent)`}},h(MdiIcon,{name:icon,size:19,color:accent})),h('div',{style:{minWidth:0}},h('div',{style:{fontSize:13,fontWeight:800,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}},title),h('div',{style:{...s.hint,color:accent,marginTop:2,fontWeight:700,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}},value)))}
export default function Card({cardId='casa-es-overview'}){const s=useStyles(),d=useDashboard();const[c]=useCardConfig(cardId,DEF);const alarm=d.getState(c.alarmEntity),garage=d.getState(c.garageEntity),guest=d.getState(c.guestEntity);return h('div',{style:{...s.card,padding:s.tokens.space.sm}},h('div',{style:{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(100px,1fr))',gap:s.tokens.space.sm}},tile(s,'mdi:shield-home','Sicurezza',alarmLabel(alarm),alarm==='triggered'?'#ff453a':alarm==='disarmed'?s.tokens.color.green:s.tokens.color.amber,()=>d.openMoreInfo(c.alarmEntity)),tile(s,'mdi:garage','Garage',garageLabel(garage),garage==='closed'?s.tokens.color.green:s.tokens.color.amber,()=>d.openMoreInfo(c.garageEntity)),tile(s,'mdi:account-star','Ospiti',guest==='on'?'Attivi':'Spenti',guest==='on'?s.tokens.color.purple:s.tokens.color.muted,()=>d.callService('input_boolean',guest==='on'?'turn_off':'turn_on',c.guestEntity))))}
